const input=$json.body??$json;
const s=v=>String(v??"").trim();
const lower=v=>s(v).toLowerCase();
const status=lower(input.status??input.lifecycle_status??input.outcome_status);
const event=lower(input.event_type??input.outcome);
const intent=lower(input.intent??input.seller_intent);
const motivation=lower(input.motivation??input.motivation_type);
const urgency=lower(input.urgency);
const pipeline=lower(input.pipeline_state??input.deal_status??input.status);
const dnc=input.dnc===true||input.dnc_suppressed===true||event==="opt_out"||status==="dnc";
const reply=s(input.seller_reply??input.inbound_message??input.message_text);
const leadId=s(input.lead_id??input.identity?.lead_id);
const propertyId=s(input.property_id??input.identity?.property_id);
const dealId=s(input.deal_id??input.identity?.deal_id);
const threadId=s(input.thread_id??input.identity?.thread_id);
const requestId=s(input.request_id??input.communication?.request_id);
const auditId=s(input.audit_id??input.communication?.audit_id);
const attempts=Math.max(0,Number(input.contact_attempts??input.attempts??0)||0);
const unanswered=Math.max(0,Number(input.unanswered_attempts??0)||0);
const daysSilent=Math.max(0,Number(input.days_since_last_contact??input.days_silent??0)||0);
const missing=[];
if(!leadId&&!dealId)missing.push("lead_id_or_deal_id");
if(!requestId&&!auditId)missing.push("request_id_or_audit_id");
let lifecycle="active_follow_up", temperature="warm", nextAction="monitor_and_follow_up", nextWorkflow="wf-099-seller-follow-up-timing-cadence", priority="normal", score=50, reason="active seller lifecycle; continue evidence-based follow-up";
if(dnc){lifecycle="suppressed";temperature="cold";nextAction="suppress_outreach";nextWorkflow=null;priority="critical";score=0;reason="DNC/opt-out; seller must remain suppressed";}
else if(reply||intent==="positive_interest"||intent==="negotiation"){lifecycle=intent==="negotiation"?"negotiating":"engaged";temperature="hot";nextAction=intent==="negotiation"?"advance_offer_negotiation":"advance_acquisition_conversation";nextWorkflow=intent==="negotiation"?"wf-080-offer-negotiation-intelligence":"wf-097-ai-seller-response-intelligence";priority="high";score=85;reason="seller engagement indicates an actionable acquisition opportunity";}
else if(["contracted","under_contract","closing"].some(x=>pipeline.includes(x))){lifecycle="transaction_active";temperature="hot";nextAction="protect_transaction_and_coordinate_close";nextWorkflow="wf-042-closing-coordination";priority="critical";score=95;reason="transaction is active; prioritize execution and closing coordination";}
else if(motivation.includes("urgent")||urgency==="high"||daysSilent<=2&&attempts>0){lifecycle="time_sensitive";temperature="hot";nextAction="time_sensitive_follow_up";nextWorkflow="wf-099-seller-follow-up-timing-cadence";priority="high";score=75;reason="seller or deal signals indicate a short decision window";}
else if(attempts>=5&&unanswered>=3){lifecycle="nurture";temperature="cold";nextAction="stop_active_pursuit_and_recycle";nextWorkflow="wf-100-seller-silence-reengagement";priority="normal";score=25;reason="contact fatigue threshold reached without response";}
else if(daysSilent>=30&&attempts>=3){lifecycle="reengagement_due";temperature="warm";nextAction="reengage_with_new_angle";nextWorkflow="wf-101-seller-reengagement-message";priority="normal";score=45;reason="seller has gone silent long enough to justify a new re-engagement angle";}
else if(intent==="negative_interest"){lifecycle="nurture";temperature="cold";nextAction="respectfully_close_or_nurture";nextWorkflow="wf-099-seller-follow-up-timing-cadence";priority="normal";score=15;reason="seller signal is negative; avoid aggressive pursuit";}
const actionId="seller-lifecycle-intel:"+((leadId||dealId||threadId||"unknown"))+":"+(requestId||auditId||"event")+":v1";
return[{json:{ok:missing.length===0,action_id:actionId,lifecycle:{state:lifecycle,temperature,priority,score,reason},acquisition_advancement:{next_action:nextAction,next_workflow:nextWorkflow,autonomous_outbound_allowed:!dnc&&["engaged","negotiating","time_sensitive","reengagement_due"].includes(lifecycle),evidence:{intent:intent||null,motivation:motivation||null,urgency:urgency||null,pipeline_state:pipeline||null,attempts,unanswered_attempts:unanswered,days_silent:daysSilent}},identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null,thread_id:threadId||null},communication:{request_id:requestId||null,audit_id:auditId||null,status:status||null,event:event||null,seller_reply_present:Boolean(reply)},missing_requirements:missing}}];

const input=$json;
const code=Number(input.statusCode??0);
const crmOk=code>=200&&code<300;
return[{json:{ok:crmOk,action_id:input.action_id??null,lifecycle:input.lifecycle??null,acquisition_advancement:input.acquisition_advancement??null,identity:input.identity??null,communication:input.communication??null,crm_state_sync:{status:crmOk?"updated":"failed",status_code:code}}}];
